{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required field")
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list) or not segments:
        raise ValueError("segments must be a non-empty list")
    if isinstance(budget, bool) or not isinstance(budget, int) or budget < 0:
        raise ValueError("budget must be a non-negative integer")

    allocations = []
    names = []
    importances = []
    total_minimum = 0
    total_capacity = 0

    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            raise ValueError("each segment must be an object")
        required = ("name", "importance", "minimum", "capacity")
        if any(field not in segment for field in required):
            raise ValueError("segment is missing a required field")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str):
            raise ValueError("segment name must be a string")
        if name in names:
            raise ValueError("segment names must be unique")
        if isinstance(importance, bool) or not isinstance(importance, int) or importance < 0:
            raise ValueError("importance must be a non-negative integer")
        if isinstance(minimum, bool) or not isinstance(minimum, int) or minimum < 0:
            raise ValueError("minimum must be a non-negative integer")
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < minimum:
            raise ValueError("capacity must be an integer at least as large as minimum")
        names.append(name)
        importances.append(importance)
        allocations.append(minimum)
        total_minimum += minimum
        total_capacity += capacity

    if budget < total_minimum or budget > total_capacity:
        raise ValueError("budget is infeasible")

    remaining = budget - total_minimum
    while remaining:
        best_index = None
        for index, segment in enumerate(segments):
            if allocations[index] >= segment["capacity"]:
                continue
            if best_index is None:
                best_index = index
                continue
            left = importances[index] * (allocations[best_index] + 1)
            right = importances[best_index] * (allocations[index] + 1)
            if left > right:
                best_index = index
        allocations[best_index] += 1
        remaining -= 1

    return {
        "allocations": allocations,
        "name_mapping": {name: index for index, name in enumerate(names)},
        "conserved_total": sum(allocations),
    }
